#!/usr/bin/env python3
"""Adapt non-Claude agent hook payloads for the shared dag_workflow guard.

Codex (PreToolUse via .codex/hooks.json) and the GUI surfaces (cursor,
antigravity) reuse the same COMMAND_RULES enforcement Claude Code gets from
github_command_guard.sh. Payloads differ slightly per surface, so this shim
extracts the shell command, runs it through the Claude-side guards —
dag_workflow.py guard (lifecycle COMMAND_RULES), prod_guard.py
(destructive-command deny-list, autonomous mode; PI-394), and admission_package.py
(supply-chain package-existence check, autonomous mode; PI-564) — and
translates a deny to the caller's dialect:

  codex  -> {"hookSpecificOutput": {permissionDecision: "deny", ...}}
            (the documented PreToolUse schema; Codex accepts it)
  cursor -> {"permission": "deny", "user_message": ...}  (beforeShellExecution)
  antigravity -> {"decision": "deny", "reason": ...}      (safety-gate PreToolUse)

Stdin differs per surface too (PI-385, confirmed from vendor docs): Codex/Claude
send {"tool_input": {"command"}}, Cursor beforeShellExecution sends a top-level
{"command"}, Antigravity sends {"toolCall": {"args": {"CommandLine"}}}.

Fail-open by design: on any parse error the command proceeds — git hooks and CI
remain the real enforcement boundary (ADR-007). The GUI surfaces keep this posture
(no Cursor `failClosed`): a hook crash must never wedge a user's shell.

Usage (wired by the scaffolded hook configs): admission_agent_adapter.py <dialect>
"""

import json
import subprocess
import sys
from pathlib import Path


def _extract_command(payload: dict) -> str:
    """Pull the shell command out of whichever stdin shape the surface sent.

    Type-guards every level: malformed JSON (non-dict payload/tool_input/args)
    yields "" rather than raising, keeping the hook fail-open.
    """
    if not isinstance(payload, dict):
        return ""
    tool_input = payload.get("tool_input") or payload.get("toolInput") or {}
    if not isinstance(tool_input, dict):
        tool_input = {}
    tool_call = payload.get("toolCall")
    call_args = tool_call.get("args") if isinstance(tool_call, dict) else None
    if not isinstance(call_args, dict):
        call_args = {}
    command = (
        tool_input.get("command")
        or tool_input.get("cmd")
        or payload.get("command")  # Cursor beforeShellExecution (top-level)
        or call_args.get("CommandLine")  # Antigravity shell tool
        or call_args.get("command")
        or ""
    )
    if isinstance(command, list):
        command = " ".join(str(part) for part in command)
    return str(command)


def _run_guard(name: str, payload: dict, *args: str) -> object:
    """Run a sibling guard script with a JSON payload; return its parsed verdict.

    Fail-open: a missing script or any error yields None (the command proceeds).
    """
    script = Path(__file__).with_name(name)
    if not script.exists():
        return None
    try:
        proc = subprocess.run(  # noqa: S603 - executes only scaffold-owned sibling guard scripts.
            [sys.executable, str(script), *args],
            input=json.dumps(payload),
            capture_output=True,
            text=True,
            check=False,
        )
        return json.loads(proc.stdout.strip() or "null")
    except (OSError, subprocess.SubprocessError, json.JSONDecodeError):
        return None


def _deny_reason(verdict: object) -> str | None:
    """Deny reason from a PreToolUse verdict (documented hookSpecificOutput or the
    legacy {"decision": "block"} shape), or None if it isn't a deny."""
    if not isinstance(verdict, dict):
        return None
    hso = verdict.get("hookSpecificOutput")
    if isinstance(hso, dict) and hso.get("permissionDecision") == "deny":
        return hso.get("permissionDecisionReason", "")
    if verdict.get("decision") == "block":
        return verdict.get("reason", "")
    return None


def main() -> int:
    dialect = sys.argv[1] if len(sys.argv) > 1 else "codex"
    try:
        payload = json.loads(sys.stdin.read() or "{}")
    except json.JSONDecodeError:
        return 0
    command = _extract_command(payload)
    if not command:
        return 0
    cwd = payload.get("cwd") if isinstance(payload, dict) else None

    # Lifecycle COMMAND_RULES guard first; only run the next guard if the
    # previous one didn't already deny — avoids extra subprocesses on a
    # blocked command (PI-394/PI-564). Agent surfaces are non-interactive, so
    # both prod_guard and package_guard run in autonomous mode → a flagged
    # command blocks outright rather than "ask"ing. All three emit the
    # documented PreToolUse shape.
    reason = _deny_reason(
        _run_guard("dag_workflow.py", {"tool_input": {"command": command}}, "guard")
    )
    if reason is None:
        reason = _deny_reason(
            _run_guard(
                "prod_guard.py",
                {
                    "tool_input": {"command": command},
                    "permission_mode": "bypassPermissions",
                    "cwd": cwd or ".",
                },
            )
        )
    if reason is None:
        reason = _deny_reason(
            _run_guard(
                "admission_package.py",
                {
                    "tool_input": {"command": command},
                    "permission_mode": "bypassPermissions",
                },
            )
        )
    if reason is None:
        return 0

    if dialect == "cursor":
        # Cursor beforeShellExecution deny (PI-385: permission + snake_case msgs).
        out = {"permission": "deny", "user_message": reason, "agent_message": reason}
    elif dialect == "antigravity":
        # Antigravity safety-gate deny (PI-385).
        out = {"decision": "deny", "reason": reason}
    else:
        # codex: the documented PreToolUse schema (Codex accepts it).
        out = {
            "hookSpecificOutput": {
                "hookEventName": "PreToolUse",
                "permissionDecision": "deny",
                "permissionDecisionReason": reason,
            }
        }
    sys.stdout.write(json.dumps(out))
    return 0


if __name__ == "__main__":
    if sys.argv[1:2] in (["-h"], ["--help"]):  # --help does no work (#992)
        print((__doc__ or "").strip())
        sys.exit(0)
    sys.exit(main())

.agents/rules/node.md:
---
description: Node.js / Bun environment and tooling
globs: ["**/*.ts", "**/*.tsx", "**/*.js", "package.json", "bun.lockb"]
alwaysApply: false
---

## Node.js environment

Uses [`bun`](https://bun.sh). Never `npm` or `npx`.

```bash
bun install       # install deps
bun run <script>  # run a package.json script
bunx <package>    # run a binary (replaces npx)
bun run lint      # lint
bun test          # tests
just sbom         # CycloneDX SBOM via cdxgen (#574) — release.yml attaches it to Releases
just license      # dependency license scan (#579) — deny GPL/AGPL; tune the recipe's --failOn list
just fuzz         # property-based tests with fast-check (#580) — runs under `bun test`; CI runs it nightly, not per-PR
```

## Property-based testing (fast-check, #580)

Add once with `bun add -d fast-check`; opt-in per file, runs under `bun test`
(`just fuzz`). Generates edge-case inputs a hand-written test wouldn't try:

```ts
import fc from "fast-check";
import { test } from "bun:test";

test("clamp stays within bounds", () => {
  fc.assert(fc.property(fc.integer(), fc.integer(), fc.integer(), (a, b, x) => {
    const [lo, hi] = a <= b ? [a, b] : [b, a];
    const r = clamp(x, lo, hi);
    return lo <= r && r <= hi;
  }));
});
```

Pattern/tooling, **not** a blocking gate — property tests live alongside unit tests.

**When it runs:** the CI `fuzz` job is schedule-only (nightly) and non-blocking —
never on a PR (#727). fast-check draws fresh seeds each run, so nightly explores
inputs a per-PR run would only repeat. Run `just fuzz` locally at will.

.agents/scripts/backfill-board-done.sh:
#!/usr/bin/env bash
# One-time backfill: move every CLOSED issue's board card to "Done".
#
# Why this exists: board-automation.yml historically set Status=Done ONLY when a
# PR with "Closes #N" merged. Issues closed any other way — manually, as a
# duplicate, as "not planned", by a PR whose body didn't match, or an epic closed
# once its children finished — stayed frozen in their previous column (Backlog /
# To Do / In Progress / In Review). The workflow now also listens for
# `issues: closed`, but that only fixes issues closed FROM NOW ON. This script
# reconciles the already-closed backlog in a single pass.
#
# Usage:
#   .agents/scripts/backfill-board-done.sh [--dry-run] [--done-name "Done"]
#
#   --dry-run      list the cards that WOULD move; change nothing.
#   --done-name    name of the target Status option (default: "Done").
#
# Requires: gh authenticated with a token carrying the 'project' scope
# (PROJECT_TOKEN, or a gh auth token with project scope). The board number comes
# from PROJECT_NUMBER or .agents/config.yaml — the same source of truth as
# setup-github.sh / create-issue.sh / board-automation.yml.

set -euo pipefail

command -v gh >/dev/null 2>&1 || {
  echo "error: GitHub CLI (gh) not found — install: https://cli.github.com" >&2
  exit 1
}

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]:-$0}")" && pwd)"
PY="$SCRIPT_DIR/../hooks/python-resolve.sh"
# shellcheck source=/dev/null
. "$SCRIPT_DIR/gh-host.sh"

DRY_RUN=0
DONE_NAME="Done"
while [ $# -gt 0 ]; do
  case "$1" in
  --dry-run) DRY_RUN=1 ;;
  --done-name)
    DONE_NAME="${2:-}"
    [ -n "$DONE_NAME" ] || {
      echo "error: --done-name needs a value" >&2
      exit 1
    }
    shift
    ;;
  -h | --help)
    sed -n '2,26p' "$0" | sed 's/^# \{0,1\}//'
    exit 0
    ;;
  *)
    echo "error: unknown option '$1'" >&2
    exit 1
    ;;
  esac
  shift
done

HOST="$(gh_host)"
if ! gh auth status -h "$HOST" >/dev/null 2>&1; then
  echo "ERROR: gh is not authenticated for $HOST. Run: gh auth login --hostname $HOST" >&2
  exit 1
fi

if [ -n "${PROJECT_TOKEN:-}" ]; then
  export GH_TOKEN="$PROJECT_TOKEN"
fi

OWNER=$(gh repo view --json owner -q .owner.login)

# Board number: PROJECT_NUMBER env overrides; else read github_project_number
# from .agents/config.yaml (shared SSOT, #556); default 1.
if [ -z "${PROJECT_NUMBER:-}" ]; then
  PROJECT_NUMBER=$(grep -E '^[[:space:]]*github_project_number:' "$SCRIPT_DIR/../config.yaml" 2>/dev/null |
    head -n1 | sed 's/#.*$//' | grep -oE '[0-9]+' | head -n1 || true)
fi
PROJECT_NUMBER="${PROJECT_NUMBER:-1}"

echo "Backfilling GitHub Project #$PROJECT_NUMBER for $OWNER (target status: '$DONE_NAME')"

# --- Resolve project id, Status field id, and the target option id. ---
# user(...) errors on an org-owned board and vice versa; tolerate it so the jq/py
# fallback selects whichever path returned data (same tactic as board-automation.yml).
META_QUERY='
  query($owner: String!, $number: Int!) {
    user(login: $owner) {
      projectV2(number: $number) {
        id
        field(name: "Status") {
          ... on ProjectV2SingleSelectField { id options { id name } }
        }
      }
    }
    organization(login: $owner) {
      projectV2(number: $number) {
        id
        field(name: "Status") {
          ... on ProjectV2SingleSelectField { id options { id name } }
        }
      }
    }
  }'

META=$(gh api graphql -f query="$META_QUERY" -f owner="$OWNER" -F number="$PROJECT_NUMBER" 2>/dev/null || true)
META_FILE=$(mktemp)
trap 'rm -f "$META_FILE"' EXIT
printf '%s' "$META" >"$META_FILE"

META_INFO=$(
  "$PY" - "$META_FILE" "$DONE_NAME" <<'PYEOF'
import sys, json
d = (json.load(open(sys.argv[1])) or {}).get("data") or {}
p = (d.get("user") or d.get("organization") or {}).get("projectV2") or {}
f = p.get("field") or {}
done = ""
for o in f.get("options") or []:
    if o.get("name") == sys.argv[2]:
        done = o["id"]
        break
print(p.get("id", ""), f.get("id", ""), done)
PYEOF
)
read -r PROJECT_ID FIELD_ID DONE_OPTION_ID <<EOF
$META_INFO
EOF

if [ -z "$PROJECT_ID" ]; then
  echo "ERROR: project #$PROJECT_NUMBER not found (or PROJECT_TOKEN lacks 'project' scope)." >&2
  exit 1
fi
if [ -z "$FIELD_ID" ]; then
  echo "ERROR: the board has no single-select 'Status' field — nothing to backfill." >&2
  exit 1
fi
if [ -z "$DONE_OPTION_ID" ]; then
  echo "ERROR: Status field has no option named '$DONE_NAME'. Pass --done-name to match your board." >&2
  exit 1
fi

# --- Walk every board item (paginated past the 100-item cap) and update each
# card whose linked issue is CLOSED but whose Status is not already the target. ---
ITEMS_QUERY='
  query($owner: String!, $number: Int!, $after: String) {
    user(login: $owner) {
      projectV2(number: $number) {
        items(first: 100, after: $after) {
          pageInfo { hasNextPage endCursor }
          nodes {
            id
            status: fieldValueByName(name: "Status") {
              ... on ProjectV2ItemFieldSingleSelectValue { name }
            }
            content { ... on Issue { number state } }
          }
        }
      }
    }
    organization(login: $owner) {
      projectV2(number: $number) {
        items(first: 100, after: $after) {
          pageInfo { hasNextPage endCursor }
          nodes {
            id
            status: fieldValueByName(name: "Status") {
              ... on ProjectV2ItemFieldSingleSelectValue { name }
            }
            content { ... on Issue { number state } }
          }
        }
      }
    }
  }'

update_card() {
  local item_id="$1"
  gh api graphql -f query='
    mutation($project: ID!, $item: ID!, $field: ID!, $option: String!) {
      updateProjectV2ItemFieldValue(input: {
        projectId: $project
        itemId: $item
        fieldId: $field
        value: { singleSelectOptionId: $option }
      }) { projectV2Item { id } }
    }' -f project="$PROJECT_ID" -f item="$item_id" \
    -f field="$FIELD_ID" -f option="$DONE_OPTION_ID" >/dev/null
}

CURSOR=""
MOVED=0
SCANNED=0
PAGE_FILE=$(mktemp)
trap 'rm -f "$META_FILE" "$PAGE_FILE"' EXIT

while :; do
  if [ -n "$CURSOR" ]; then
    PAGE=$(gh api graphql -f query="$ITEMS_QUERY" -f owner="$OWNER" \
      -F number="$PROJECT_NUMBER" -f after="$CURSOR" 2>/dev/null || true)
  else
    PAGE=$(gh api graphql -f query="$ITEMS_QUERY" -f owner="$OWNER" \
      -F number="$PROJECT_NUMBER" 2>/dev/null || true)
  fi
  [ -n "$PAGE" ] || {
    echo "ERROR: failed to read a page of board items." >&2
    exit 1
  }
  printf '%s' "$PAGE" >"$PAGE_FILE"

  # First stdout line: "<hasNextPage> <endCursor>". Remaining lines:
  # "<itemId> <issueNumber>" for each CLOSED card not already at the target.
  PARSED=$(
    "$PY" - "$PAGE_FILE" "$DONE_NAME" <<'PYEOF'
import sys, json
d = (json.load(open(sys.argv[1])) or {}).get("data") or {}
p = (d.get("user") or d.get("organization") or {}).get("projectV2") or {}
items = p.get("items") or {}
info = items.get("pageInfo") or {}
print(("true" if info.get("hasNextPage") else "false"), info.get("endCursor") or "")
for node in items.get("nodes") or []:
    content = node.get("content") or {}
    if content.get("state") != "CLOSED":
        continue
    if ((node.get("status") or {}).get("name")) == sys.argv[2]:
        continue
    num = content.get("number")
    print(node["id"], num if num is not None else "?")
PYEOF
  )

  HEAD=$(printf '%s\n' "$PARSED" | head -n1)
  HAS_NEXT=$(printf '%s' "$HEAD" | cut -d' ' -f1)
  CURSOR=$(printf '%s' "$HEAD" | cut -d' ' -f2-)

  while read -r ITEM_ID ISSUE_NUM; do
    [ -n "$ITEM_ID" ] || continue
    SCANNED=$((SCANNED + 1))
    if [ "$DRY_RUN" = 1 ]; then
      echo "  would move #$ISSUE_NUM -> $DONE_NAME"
    else
      if update_card "$ITEM_ID"; then
        echo "  moved #$ISSUE_NUM -> $DONE_NAME"
        MOVED=$((MOVED + 1))
      else
        echo "  WARNING: failed to move #$ISSUE_NUM" >&2
      fi
    fi
  done <<EOF
$(printf '%s\n' "$PARSED" | tail -n +2)
EOF

  [ "$HAS_NEXT" = "true" ] || break
  [ -n "$CURSOR" ] || break
done

if [ "$DRY_RUN" = 1 ]; then
  echo "Dry run: $SCANNED closed card(s) would move to '$DONE_NAME'. Re-run without --dry-run to apply."
else
  echo "Done: moved $MOVED card(s) to '$DONE_NAME'."
fi

.agents/scripts/check-test-contract.py:
#!/usr/bin/env python3
"""Mechanise the cross-repo test contract's rules that pytest itself cannot see.

    check-test-contract.py exit-codes [PATH ...]   (default: tests)
    check-test-contract.py discovery [DIR]         (default: tests)

exit-codes (rule 2, exact exit codes): a test asserts the exit code it expects,
never "non-zero". A crash, a usage error and a refusal are different answers,
and ``assert proc.returncode != 0`` passes all three. Flagged, in any
``assert``: ``!= 0`` or ``> 0`` against an exit code (``.returncode``,
``.exit_code``, ``rc`` ...), ``not ... == 0``, or the exit code's bare
truthiness. An ``if returncode != 0:`` guard is not an assertion and is left
alone. The ratchet is zero: an assertion that truly cannot name one code keeps
its place only with a reason on its first line::

    assert proc.returncode != 0  # test-contract: nonzero-ok: <why no one code>

discovery (rule 4, every suite is in the manifest): for pytest the manifest is
discovery itself, so a file under DIR that defines a ``test_`` function (at
module level, or in a ``Test*`` class) but that a full ``pytest --collect-only``
from the current directory does not reach runs nowhere, and nothing says so:
``tests/check_upgrade.py`` holding ``def test_...`` is the usual case. Rename
it to ``test_*.py``, or move the function out if it is not a test. Collection
runs under ``sys.executable``, so run this with the project's interpreter
(``uv run python``).

Exit codes: 0 clean, 1 a finding (each printed as path:line), 2 usage. Stdlib only.
"""

from __future__ import annotations

import argparse
import ast
import re
import subprocess
import sys
from pathlib import Path

_EXIT_ATTRS = {"returncode", "exit_code", "exitcode", "exit_status"}
_EXIT_NAMES = re.compile(r"^(?:.*_)?(?:rc|returncode|exit_code|exitcode|exit_status)$")
_EXEMPT = re.compile(r"#\s*test-contract:\s*nonzero-ok:\s*\S")


def _is_exit_code(node: ast.expr) -> bool:
    if isinstance(node, ast.Attribute):
        return node.attr in _EXIT_ATTRS
    return isinstance(node, ast.Name) and bool(_EXIT_NAMES.match(node.id))


def _is_zero(node: ast.expr) -> bool:
    return isinstance(node, ast.Constant) and node.value == 0 and not isinstance(node.value, bool)


def _nonzero_compare(node: ast.Compare) -> bool:
    """`<code> != 0`, `<code> > 0`, `0 != <code>` or `0 < <code>`."""
    if len(node.ops) != 1:
        return False
    left, op, right = node.left, node.ops[0], node.comparators[0]
    if _is_exit_code(left) and _is_zero(right):
        return isinstance(op, (ast.NotEq, ast.Gt))
    if _is_zero(left) and _is_exit_code(right):
        return isinstance(op, (ast.NotEq, ast.Lt))
    return False


def _eq_zero(node: ast.expr) -> bool:
    if not isinstance(node, ast.Compare) or len(node.ops) != 1:
        return False
    sides = (node.left, node.comparators[0])
    return (
        isinstance(node.ops[0], ast.Eq)
        and any(map(_is_zero, sides))
        and any(map(_is_exit_code, sides))
    )


def _asserts_nonzero(test: ast.expr) -> bool:
    """True when *test*, or any `and`/`or` operand of it, only says "not zero".

    An `or` operand counts too: `assert rc != 0 or cond` passes for every non-zero code.
    """
    if isinstance(test, ast.BoolOp):
        return any(_asserts_nonzero(value) for value in test.values)
    if isinstance(test, ast.Compare):
        return _nonzero_compare(test)
    if isinstance(test, ast.UnaryOp) and isinstance(test.op, ast.Not):
        return _eq_zero(test.operand)
    return _is_exit_code(test)


def exit_code_findings(path: Path) -> list[str]:
    """Each non-exact exit-code assertion in *path*, as ``path:line: text``."""
    source = path.read_text(encoding="utf-8")
    try:
        tree = ast.parse(source, filename=str(path))
    except SyntaxError as err:
        return [f"{path}:{err.lineno}: cannot parse ({err.msg})"]
    lines = source.splitlines()
    findings = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Assert) and _asserts_nonzero(node.test):
            text = lines[node.lineno - 1]
            if not _EXEMPT.search(text):
                findings.append(f"{path}:{node.lineno}: {text.strip()}")
    return findings


def _defines_tests(path: Path) -> int | None:
    """The line of the first test function pytest would look for in *path*, else None."""
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    except (SyntaxError, UnicodeDecodeError):
        return None
    funcs = (ast.FunctionDef, ast.AsyncFunctionDef)
    for node in tree.body:
        if isinstance(node, funcs) and node.name.startswith("test"):
            return node.lineno
        if isinstance(node, ast.ClassDef) and node.name.startswith("Test"):
            for item in node.body:
                if isinstance(item, funcs) and item.name.startswith("test"):
                    return item.lineno
    return None


def collected_files(root: Path) -> set[Path] | str:
    """The files a full pytest collection from *root* reaches, or why it failed."""
    argv = [sys.executable, "-m", "pytest", "--collect-only", "-q", "-p", "no:cacheprovider"]
    proc = subprocess.run(  # noqa: S603 — fixed argv, no shell
        [*argv, f"--rootdir={root}"], capture_output=True, text=True, cwd=root, check=False
    )
    if proc.returncode not in (0, 5):  # 5: nothing collected, which is an answer
        tail = "\n".join((proc.stdout + proc.stderr).strip().splitlines()[-15:])
        return f"pytest --collect-only exited {proc.returncode}:\n{tail}"
    return {
        (root / line.split("::", 1)[0]).resolve()
        for line in proc.stdout.splitlines()
        if "::" in line
    }


def discovery_findings(root: Path, tests: Path) -> list[str]:
    """Each file under *tests* that defines a test no full collection reaches."""
    candidates = {}
    for path in sorted(tests.rglob("*.py")):
        line = _defines_tests(path)
        if line is not None:
            candidates[path.resolve()] = (path, line)
    if not candidates:
        return []
    reached = collected_files(root)
    if isinstance(reached, str):
        return [reached]
    return [
        f"{path}:{line}: defines a test that pytest never collects"
        for resolved, (path, line) in candidates.items()
        if resolved not in reached
    ]


def _python_files(roots: list[Path]) -> list[Path]:
    files: list[Path] = []
    for root in roots:
        files.extend([root] if root.is_file() else sorted(root.rglob("*.py")))
    return files


def main(argv: list[str] | None = None) -> int:
    """Run one check; return its exit code."""
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    sub = parser.add_subparsers(dest="check", required=True)
    codes = sub.add_parser("exit-codes", help="rule 2: no 'non-zero' exit-code assertion")
    codes.add_argument("paths", nargs="*", type=Path, default=[Path("tests")])
    found = sub.add_parser("discovery", help="rule 4: every test file is collected")
    found.add_argument("dir", nargs="?", type=Path, default=Path("tests"))
    args = parser.parse_args(argv)
    if args.check == "discovery":
        return _discovery(parser, args.dir)
    missing = [str(p) for p in args.paths if not p.exists()]
    if missing and missing != ["tests"]:
        parser.error(f"no such path: {', '.join(missing)}")
    findings = [
        f
        for p in _python_files([p for p in args.paths if p.exists()])
        for f in exit_code_findings(p)
    ]
    for finding in findings:
        print(finding)
    if findings:
        print(
            f"test contract rule 2: {len(findings)} assertion(s) accept any non-zero exit. "
            "Assert the exact code, or add `# test-contract: nonzero-ok: <reason>`.",
            file=sys.stderr,
        )
        return 1
    return 0


def _discovery(parser: argparse.ArgumentParser, tests: Path) -> int:
    if not tests.is_dir():
        if tests == Path("tests"):
            return 0  # nothing to discover yet
        parser.error(f"no such directory: {tests}")
    findings = discovery_findings(Path.cwd(), tests)
    for finding in findings:
        print(finding)
    if findings:
        print(
            f"test contract rule 4: {len(findings)} file(s) under {tests} run nowhere. "
            "Name them test_*.py or *_test.py, or move the non-test out.",
            file=sys.stderr,
        )
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

